// Notfallordner-Briefkasten (Cloudflare Worker + KV)
//
// Speichert nur verschlüsselte Einsendungen. Lesen kann sie ausschließlich das Programm des Beraters
// mit seinem privaten Schlüssel. Nach dem Abholen werden sie gelöscht, spätestens nach 30 Tagen.
//
// Benötigt:  KV-Namespace gebunden als  NFO
//            Geheimnis (Secret)          ADMIN_TOKEN  (Zugangsschlüssel für das Programm)

const FORMULAR_HTML = "<!doctype html>\n<html lang=\"de\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Notfallordner – Ihre Notfallkontakte</title>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&display=swap\">\n<style>\n:root {\n  --bg: #f3f4f6; --surface: #ffffff; --ink: #1d232b; --muted: #5d6673; --line: #d9dde3;\n  --accent: #b3262e; --accent-soft: #f8e4e5; --accent-ink: #ffffff; --ok: #1f7a4d; --ok-soft: #e1f2e9; --focus: #2b5fd9;\n  --f-display: \"Bricolage Grotesque\", \"Segoe UI\", system-ui, sans-serif;\n  --f-body: \"Atkinson Hyperlegible\", \"Segoe UI\", system-ui, sans-serif;\n}\n@media (prefers-color-scheme: dark) {\n  :root { --bg: #15181d; --surface: #1e232a; --ink: #e8eaee; --muted: #9aa3af; --line: #343b45;\n    --accent: #ef6a70; --accent-soft: #3a2226; --accent-ink: #1a0d0e; --ok: #5bc48e; --ok-soft: #1d3329; --focus: #7da2ff; color-scheme: dark; }\n}\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody { background: var(--bg); color: var(--ink); font-family: var(--f-body); font-size: 16px; line-height: 1.5;\n  padding: max(16px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) 48px max(16px, env(safe-area-inset-left)); }\n[hidden] { display: none !important; }\n.wrap { max-width: 860px; margin: 0 auto; display: grid; gap: 16px; }\nheader { display: flex; align-items: center; gap: 12px; padding-top: 8px; }\n.cross { width: 40px; height: 40px; border-radius: 9px; background: var(--accent); display: grid; place-items: center; flex: none; }\n.cross::before { content: \"\"; width: 20px; height: 20px; background:\n  linear-gradient(var(--accent-ink),var(--accent-ink)) center/6px 20px no-repeat, linear-gradient(var(--accent-ink),var(--accent-ink)) center/20px 6px no-repeat; }\nh1 { font-family: var(--f-display); font-weight: 800; font-size: clamp(1.6rem, 5vw, 2.1rem); margin: 0; line-height: 1.1; }\nh2 { font-family: var(--f-display); font-weight: 600; font-size: 1.25rem; margin: 0; }\nh3 { font-size: 1rem; margin: 0; }\np { margin: 0; }\n.hint { color: var(--muted); font-size: 0.92rem; }\nsection.card { background: var(--surface); border: 1px solid var(--line); border-radius: 12px; padding: 18px; display: grid; gap: 12px; min-width: 0; }\n.intro { display: grid; gap: 8px; }\n.lock { display: flex; gap: 10px; align-items: flex-start; background: var(--ok-soft); border-radius: 10px; padding: 12px 14px; font-size: 0.93rem; }\n.lock b { color: var(--ok); }\n.fields { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 2px 14px; }\n.f { display: grid; gap: 4px; min-width: 0; }\n.f label { font-size: 0.82rem; font-weight: 700; color: var(--muted); }\n.f .msg { font-size: 0.8rem; line-height: 1.3; color: var(--muted); height: 2.6em; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }\n.f.invalid input { border-color: var(--accent); background: var(--accent-soft); box-shadow: inset 0 0 0 1px var(--accent); }\n.f.invalid .msg { color: var(--accent); font-weight: 700; }\n.f.valid input { border-color: var(--ok); }\n.f.valid .msg { color: var(--ok); }\ninput { font: inherit; color: var(--ink); background: var(--surface); border: 1px solid var(--line); border-radius: 8px; padding: 9px 11px; width: 100%; min-height: 44px; }\ninput::placeholder { color: var(--muted); opacity: .6; }\nbutton { font: inherit; border-radius: 8px; border: 1px solid var(--line); background: var(--surface); color: var(--ink); padding: 9px 14px; cursor: pointer; min-height: 44px; }\nbutton.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); font-weight: 700; font-size: 1.05rem; }\nbutton:disabled { opacity: .55; cursor: not-allowed; }\n:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }\n.contact { border: 1px solid var(--line); border-radius: 10px; padding: 14px; display: grid; gap: 10px; }\n.contact-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; }\n.consent { display: flex; gap: 10px; align-items: flex-start; font-size: 0.93rem; }\n.consent input { width: 22px; height: 22px; min-height: 0; flex: none; margin-top: 2px; accent-color: var(--accent); }\n.summary { padding: 10px 12px; border-radius: 8px; background: var(--bg); font-size: 0.93rem; }\n.summary.warn { background: var(--accent-soft); color: var(--accent); font-weight: 700; }\n.issues { margin: 0; padding-left: 20px; font-size: 0.9rem; color: var(--accent); display: grid; gap: 2px; }\n.issues button { border: 0; background: none; color: inherit; padding: 0; min-height: 0; text-decoration: underline; text-align: left; font-size: inherit; }\n.center { text-align: center; display: grid; gap: 10px; justify-items: center; padding: 32px 18px; }\n.big { font-size: 3rem; line-height: 1; }\n#err { color: var(--accent); font-weight: 700; }\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header><div class=\"cross\" aria-hidden=\"true\"></div><h1>Notfallordner</h1></header>\n\n  <section class=\"card center\" id=\"laden\"><p class=\"hint\">Formular wird geladen …</p></section>\n\n  <section class=\"card center\" id=\"ungueltig\" hidden>\n    <div class=\"big\" aria-hidden=\"true\">🔒</div>\n    <h2 id=\"ungueltigTitel\">Dieser Link ist nicht mehr gültig</h2>\n    <p class=\"hint\" id=\"ungueltigText\">Bitte fragen Sie Ihren Berater nach einem neuen Link.</p>\n  </section>\n\n  <section class=\"card center\" id=\"fertig\" hidden>\n    <div class=\"big\" aria-hidden=\"true\">✓</div>\n    <h2>Vielen Dank! Ihre Notfallkontakte sind angekommen.</h2>\n    <p class=\"hint\">Ihr Berater meldet sich bei Ihnen. Sie können dieses Fenster jetzt schließen.</p>\n  </section>\n\n  <form id=\"formular\" hidden novalidate>\n    <div class=\"wrap\">\n      <section class=\"card intro\">\n        <h2>Ihre Notfallkontakte</h2>\n        <p>Für Ihren Notfallordner benötigt Ihr Berater <b id=\"beraterName\">–</b> noch die Personen, die im Notfall verständigt werden sollen. Bitte tragen Sie mindestens eine und höchstens drei Personen ein. Felder mit * werden benötigt.</p>\n        <div class=\"lock\"><span aria-hidden=\"true\">🔒</span><span><b>Ende-zu-Ende verschlüsselt:</b> Ihre Angaben werden schon auf Ihrem Gerät verschlüsselt. Lesen kann sie nur Ihr Berater.</span></div>\n      </section>\n\n      <section class=\"card\" aria-labelledby=\"h-nf\">\n        <h2 id=\"h-nf\">Notfallkontakte</h2>\n        <p class=\"hint\">Am besten Personen aus Ihrem nahen Umfeld, die gut erreichbar sind.</p>\n        <div id=\"kontakte\" style=\"display:grid;gap:12px\"></div>\n        <button type=\"button\" id=\"mehr\">+ Weiteren Notfallkontakt hinzufügen</button>\n      </section>\n\n      <section class=\"card\">\n        <h2>Absenden</h2>\n        <div class=\"summary\" id=\"summary\"></div>\n        <ul class=\"issues\" id=\"issues\" hidden></ul>\n        <label class=\"consent\"><input type=\"checkbox\" id=\"ok\"><span>Ich bin einverstanden, dass diese Angaben an meinen Berater übermittelt und für meinen Notfallordner verwendet werden. Die eingetragenen Personen sind damit einverstanden, als Notfallkontakt genannt zu werden. <span id=\"dsHinweis\"></span></span></label>\n        <button type=\"submit\" class=\"primary\" id=\"senden\">Verschlüsselt senden</button>\n        <p id=\"err\" role=\"alert\"></p>\n      </section>\n    </div>\n  </form>\n</div>\n<div id=\"lists\"></div>\n\n<script>// Gemeinsame Felder und Prüfungen für Kundenformular (Briefkasten) und Windows-Programm.\n// Stellt window.NFO bereit.\n(function () {\n  const VERWANDT = [\"Ehepartner\",\"Ehepartnerin\",\"Lebenspartner\",\"Lebenspartnerin\",\"Vater\",\"Mutter\",\"Bruder\",\"Schwester\",\"Sohn\",\"Tochter\",\"Cousin\",\"Cousine\",\"Onkel\",\"Tante\",\"Ex-Mann\",\"Ex-Frau\",\"Freund\",\"Freundin\",\"Arbeitskollege\",\"Arbeitskollegin\",\"Nachbar\",\"Nachbarin\",\"Steuerberater\",\"Steuerberaterin\",\"Notar\",\"Notarin\",\"Rechtsanwalt\",\"Rechtsanwältin\",\"Vermögensverwalter\",\"Vermögensverwalterin\"];\n  const POSITION = [\"Repräsentant\",\"Repräsentantin\",\"Juniorberater\",\"Juniorberaterin\",\"Seniorberater\",\"Seniorberaterin\",\"Teamleiter\",\"Teamleiterin\",\"Repräsentanzleiter\",\"Repräsentanzleiterin\",\"Branch Manager\",\"Branch Managerin\",\"Regional Manager\",\"Regional Managerin\",\"Divisional Manager\",\"Divisional Managerin\",\"General Manager\",\"General Managerin\",\"Sales Consultant\",\"Sales Consultantin\",\"Senior Sales Consultant\",\"Senior Sales Consultantin\",\"Sales Manager\",\"Sales Managerin\",\"Senior Sales Manager\",\"Senior Sales Managerin\",\"General Sales Manager\",\"General Sales Managerin\"];\n\n  // [Schlüssel, Beschriftung, Typ/Liste, Platzhalter]\n  const F_KUNDE = [\n    [\"anrede\", \"Anrede\", \"list:dl-anrede\", \"Herr / Frau\"], [\"vorname\", \"Vorname (alle)\", \"\", \"Max Peter\"], [\"name\", \"Name\", \"\", \"Mustermann\"],\n    [\"gebdat\", \"Geburtsdatum\", \"date\"], [\"gebort\", \"Geburtsort\", \"\", \"Köln\"],\n    [\"strasse\", \"Straße, Hs.-Nr.\", \"\", \"Musterstraße 12\"], [\"plzort\", \"PLZ, Ort\", \"\", \"40212 Düsseldorf\"],\n    [\"svnr\", \"SozialVersNr.\", \"\", \"12 150372 M 001\"], [\"steuerid\", \"Steuer-ID\", \"\", \"11 Ziffern\"], [\"perso\", \"PersonalausweisNr.\", \"\", \"9 Zeichen\"], [\"iban\", \"IBAN\", \"\", \"DE..\"],\n  ];\n  const F_NF = [\n    [\"anrede\", \"Anrede\", \"list:dl-anrede\", \"Herr / Frau\"], [\"vorname\", \"Vorname\", \"\"], [\"name\", \"Name\", \"\"],\n    [\"gebdat\", \"Geburtsdatum\", \"date\"], [\"strasse\", \"Straße, Hs.-Nr.\", \"\"], [\"plzort\", \"PLZ, Ort\", \"\", \"40212 Düsseldorf\"],\n    [\"tel\", \"Telefon\", \"\"], [\"handy\", \"Handynummer\", \"\"], [\"mail\", \"Mailadresse\", \"\"],\n    [\"verwandt\", \"Verwandtschaftsverhältnis\", \"list:dl-verwandt\"], [\"beruf\", \"Beruf\", \"\"],\n  ];\n  const F_ARZT = [[\"praxis\", \"Name der Praxis\", \"\"], [\"strasse\", \"Straße, Hs.-Nr.\", \"\"], [\"plzort\", \"PLZ, Ort\", \"\"], [\"tel\", \"Telefon\", \"\"]];\n  const F_BERATER = [\n    [\"anrede\", \"Anrede\", \"list:dl-anrede\", \"Herr / Frau\"], [\"name\", \"Berater (Vor- und Nachname)\", \"\"], [\"position\", \"Position\", \"list:dl-position\"],\n    [\"strasse\", \"Büro Straße, Hs.-Nr.\", \"\"], [\"plzort\", \"Büro PLZ, Ort\", \"\"], [\"mail\", \"Berater Mailadresse\", \"\"],\n    [\"handy\", \"Berater Handynummer\", \"\"], [\"festnetz\", \"Berater FestnetzNr.\", \"\"], [\"fax\", \"Berater FaxNr.\", \"\"],\n    [\"ausweis\", \"BeraterausweisNr.\", \"\"], [\"gebdat\", \"Berater Geburtsdatum\", \"date\"], [\"gebort\", \"Berater Geburtsort\", \"\"],\n  ];\n  const REQUIRED = {\n    kunde: [\"anrede\", \"vorname\", \"name\", \"gebdat\", \"gebort\", \"strasse\", \"plzort\"],\n    \"nf.0\": [\"vorname\", \"name\", \"plzort\"],\n    berater: [\"anrede\", \"name\", \"strasse\", \"plzort\", \"mail\", \"handy\"],\n  };\n\n  const t = (s) => String(s ?? \"\").trim();\n  const esc = (s) => String(s ?? \"\").replace(/[&<>\"]/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\" }[c]));\n  const isoToDate = (iso) => { const m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(iso || \"\"); return m ? new Date(+m[1], +m[2] - 1, +m[3]) : null; };\n  const heute = () => { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), d.getDate()); };\n  const digits = (s) => String(s).replace(/\\D/g, \"\");\n  const compact = (s) => String(s).replace(/[\\s.-]/g, \"\").toUpperCase();\n\n  function steuerIdOk(d) {\n    let p = 10;\n    for (let i = 0; i < 10; i++) { let s = (+d[i] + p) % 10; if (s === 0) s = 10; p = (s * 2) % 11; }\n    return (11 - p) % 10 === +d[10];\n  }\n  function ibanOk(iban) {\n    const r = iban.slice(4) + iban.slice(0, 4); let m = 0;\n    for (const ch of r) { const v = /[A-Z]/.test(ch) ? String(ch.charCodeAt(0) - 55) : ch; for (const x of v) m = (m * 10 + +x) % 97; }\n    return m === 1;\n  }\n  function svnrOk(s) {\n    const n = s.slice(0, 8) + String(s.charCodeAt(8) - 64).padStart(2, \"0\") + s.slice(9, 11);\n    const w = [2, 1, 2, 5, 7, 1, 2, 1, 2, 1, 2, 1]; let sum = 0;\n    for (let i = 0; i < 12; i++) { const p = +n[i] * w[i]; sum += Math.floor(p / 10) + (p % 10); }\n    return sum % 10 === +s[11];\n  }\n  const phoneRule = (v) => {\n    if (/[^\\d\\s+/()-]/.test(v)) return { ok: false, msg: \"Nur Ziffern, Leerzeichen und + / - ( ) erlaubt\" };\n    const n = digits(v).length;\n    if (n < 6) return { ok: false, msg: `Mindestens 6 Ziffern – ${n} eingegeben` };\n    if (n > 15) return { ok: false, msg: `Höchstens 15 Ziffern – ${n} eingegeben` };\n    return { ok: true, msg: \"\" };\n  };\n  const RULES = {\n    steuerid: (v) => {\n      if (/[^\\d\\s]/.test(v)) return { ok: false, msg: \"Nur Ziffern erlaubt\" };\n      const d = digits(v);\n      if (d.length < 11) return { ok: false, msg: `11 Ziffern – ${d.length} eingegeben, noch ${11 - d.length}` };\n      if (d.length > 11) return { ok: false, msg: `11 Ziffern – ${d.length} eingegeben, ${d.length - 11} zu viel` };\n      if (d[0] === \"0\") return { ok: false, msg: \"Die Steuer-ID beginnt nie mit 0\" };\n      if (!steuerIdOk(d)) return { ok: false, msg: \"Prüfziffer stimmt nicht – bitte Zahlendreher prüfen\" };\n      return { ok: true, msg: \"Steuer-ID gültig\" };\n    },\n    iban: (v) => {\n      const c = compact(v);\n      if (/[^A-Z0-9]/.test(c)) return { ok: false, msg: \"Nur Buchstaben und Ziffern erlaubt\" };\n      if (!/^[A-Z]{2}/.test(c)) return { ok: false, msg: \"Beginnt mit dem Ländercode, z. B. DE\" };\n      const len = c.startsWith(\"DE\") ? 22 : null;\n      if (len && c.length !== len) return { ok: false, msg: `Deutsche IBAN: 22 Zeichen – ${c.length} eingegeben` + (c.length < 22 ? `, noch ${22 - c.length}` : `, ${c.length - 22} zu viel`) };\n      if (!len && (c.length < 15 || c.length > 34)) return { ok: false, msg: `IBAN: 15 bis 34 Zeichen – ${c.length} eingegeben` };\n      if (!ibanOk(c)) return { ok: false, msg: \"Prüfziffer stimmt nicht – bitte Zahlendreher prüfen\" };\n      return { ok: true, msg: \"IBAN gültig\" };\n    },\n    svnr: (v, ctx) => {\n      const c = compact(v);\n      if (c.length < 12) return { ok: false, msg: `12 Zeichen – ${c.length} eingegeben, noch ${12 - c.length}` };\n      if (c.length > 12) return { ok: false, msg: `12 Zeichen – ${c.length} eingegeben, ${c.length - 12} zu viel` };\n      if (!/^\\d{8}[A-Z]\\d{3}$/.test(c)) return { ok: false, msg: \"Aufbau: 8 Ziffern, 1 Buchstabe, 3 Ziffern\" };\n      if (!svnrOk(c)) return { ok: false, msg: \"Prüfziffer stimmt nicht – bitte Zahlendreher prüfen\" };\n      const g = isoToDate(ctx && ctx.gebdat);\n      if (g) {\n        const ttmmjj = String(g.getDate()).padStart(2, \"0\") + String(g.getMonth() + 1).padStart(2, \"0\") + String(g.getFullYear()).slice(2);\n        if (c.slice(2, 8) !== ttmmjj) return { ok: false, msg: `Ziffern 3–8 müssen das Geburtsdatum sein (${ttmmjj})` };\n      }\n      return { ok: true, msg: \"Sozialversicherungsnummer gültig\" };\n    },\n    perso: (v) => {\n      const c = compact(v);\n      if (/[^0-9CFGHJKLMNPRTVWXYZ]/.test(c)) return { ok: false, msg: \"Ungültiges Zeichen (kein A, B, D, E, I, O, Q, S, U)\" };\n      if (c.length < 9) return { ok: false, msg: `9 Zeichen – ${c.length} eingegeben, noch ${9 - c.length}` };\n      if (c.length > 10) return { ok: false, msg: `9 Zeichen – ${c.length} eingegeben, zu viele` };\n      return { ok: true, msg: \"\" };\n    },\n    plzort: (v) => {\n      const m = /^(\\d*)\\s*(.*)$/.exec(t(v));\n      if (!m[1]) return { ok: false, msg: \"Erst die 5-stellige PLZ, dann der Ort\" };\n      if (m[1].length !== 5) return { ok: false, msg: `PLZ hat 5 Ziffern – ${m[1].length} eingegeben` };\n      if (!m[2]) return { ok: false, msg: \"Nach der PLZ fehlt der Ort\" };\n      return { ok: true, msg: \"\" };\n    },\n    strasse: (v) => /[1-9]/.test(v) ? { ok: true, msg: \"\" } : { ok: false, msg: \"Hausnummer fehlt (z. B. Musterstraße 12)\" },\n    mail: (v) => /^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i.test(t(v)) ? { ok: true, msg: \"\" } : { ok: false, msg: \"E-Mail-Adresse unvollständig (z. B. name@beispiel.de)\" },\n    tel: phoneRule, handy: phoneRule, festnetz: phoneRule, fax: phoneRule,\n    anrede: (v) => /^(Herr|Frau)$/.test(t(v)) ? { ok: true, msg: \"\" } : { ok: false, msg: \"Bitte „Herr“ oder „Frau“\" },\n    name: (v) => /\\d/.test(v) ? { ok: false, msg: \"Namen enthalten keine Ziffern\" } : { ok: true, msg: \"\" },\n    vorname: (v) => /\\d/.test(v) ? { ok: false, msg: \"Namen enthalten keine Ziffern\" } : { ok: true, msg: \"\" },\n    gebdat: (v) => {\n      const d = isoToDate(v); if (!d) return { ok: false, msg: \"Datum unvollständig\" };\n      if (d > heute()) return { ok: false, msg: \"Geburtsdatum liegt in der Zukunft\" };\n      if (heute().getFullYear() - d.getFullYear() > 115) return { ok: false, msg: \"Geburtsdatum liegt zu weit zurück\" };\n      return { ok: true, msg: \"\" };\n    },\n  };\n\n  const group = (path) => path.split(\".\")[0];\n  const isRequired = (path, k) => (REQUIRED[path] || []).includes(k);\n  function ruleFor(path, k) {\n    if (group(path) === \"termin\") return null;\n    if (path === \"berater\" && k === \"gebdat\") return null;\n    return RULES[k] || null;\n  }\n  function checkValue(path, k, v, ctx) {\n    if (!t(v)) return null;\n    const r = ruleFor(path, k);\n    return r ? r(v, ctx) : null;\n  }\n  function tidyValue(k, v) {\n    let n = v;\n    if (k === \"iban\") { const c = compact(v); if (/^[A-Z]{2}\\d{2}[A-Z0-9]+$/.test(c)) n = c.replace(/(.{4})/g, \"$1 \").trim(); }\n    if (k === \"steuerid\") { const d = digits(v); if (d.length === 11 && !/[^\\d\\s]/.test(v)) n = `${d.slice(0, 2)} ${d.slice(2, 5)} ${d.slice(5, 8)} ${d.slice(8)}`; }\n    if (k === \"svnr\") { const c = compact(v); if (/^\\d{8}[A-Z]\\d{3}$/.test(c)) n = `${c.slice(0, 2)} ${c.slice(2, 8)} ${c[8]} ${c.slice(9)}`; }\n    if (k === \"perso\") n = compact(v);\n    if (k === \"anrede\") { const a = t(v).toLowerCase(); if (a === \"herr\" || a === \"frau\") n = a[0].toUpperCase() + a.slice(1); }\n    return n;\n  }\n\n  function fieldHtml(path, f, val) {\n    const [k, label, type, ph] = f;\n    const id = \"in-\" + path.replace(/\\./g, \"-\") + \"-\" + k;\n    const list = type && type.startsWith(\"list:\") ? ` list=\"${type.slice(5)}\"` : \"\";\n    const ty = type === \"date\" ? \"date\" : \"text\";\n    const req = isRequired(path, k) ? \" *\" : \"\";\n    return `<div class=\"f\"><label for=\"${id}\">${esc(label)}${req}</label><input id=\"${id}\" type=\"${ty}\"${list} data-path=\"${path}\" data-key=\"${k}\" value=\"${esc(val)}\"${ph ? ` placeholder=\"${esc(ph)}\"` : \"\"} autocomplete=\"off\" aria-describedby=\"${id}-msg\"><small class=\"msg\" id=\"${id}-msg\" aria-live=\"polite\"></small></div>`;\n  }\n  const fieldsHtml = (path, fields, obj) => `<div class=\"fields\">${fields.map((f) => fieldHtml(path, f, (obj || {})[f[0]])).join(\"\")}</div>`;\n  const datalists = () =>\n    `<datalist id=\"dl-anrede\"><option value=\"Herr\"><option value=\"Frau\"></datalist>` +\n    `<datalist id=\"dl-verwandt\">${VERWANDT.map((v) => `<option value=\"${v}\">`).join(\"\")}</datalist>` +\n    `<datalist id=\"dl-position\">${POSITION.map((v) => `<option value=\"${v}\">`).join(\"\")}</datalist>`;\n\n  // Feldzustand anzeigen. mark=true: Feld wurde verlassen -> Fehler rot\n  function showCheck(el, mark, ctx) {\n    const box = el.closest(\".f\"), msg = box && box.querySelector(\".msg\");\n    if (!msg) return;\n    const res = checkValue(el.dataset.path, el.dataset.key, el.value, ctx);\n    const wasRed = box.classList.contains(\"invalid\");\n    if (!res) { box.classList.remove(\"invalid\", \"valid\"); msg.textContent = \"\"; el.removeAttribute(\"aria-invalid\"); return; }\n    msg.textContent = res.msg;\n    if (res.ok) { box.classList.remove(\"invalid\"); box.classList.toggle(\"valid\", !!res.msg); el.removeAttribute(\"aria-invalid\"); }\n    else { box.classList.remove(\"valid\"); if (mark || wasRed) { box.classList.add(\"invalid\"); el.setAttribute(\"aria-invalid\", \"true\"); } }\n  }\n\n  // Alle Probleme eines Datensatzes\n  function collectIssues(daten, berater, nurKontakte) {\n    const out = [];\n    const ctx = { gebdat: daten.kunde && daten.kunde.gebdat };\n    const scan = (path, fields, obj, title, tab) => fields.forEach((f) => {\n      const k = f[0], v = (obj || {})[k];\n      const res = checkValue(path, k, v, ctx);\n      if (res && !res.ok) out.push({ path, k, tab, text: `${title}: ${f[1]}`, why: res.msg, kind: \"invalid\" });\n      else if (!t(v) && isRequired(path, k)) out.push({ path, k, tab, text: `${title}: ${f[1]}`, why: \"fehlt\", kind: \"missing\" });\n    });\n    if (!nurKontakte) scan(\"kunde\", F_KUNDE, daten.kunde, \"Kunde\");\n    (daten.nf || []).forEach((n, i) => { if (i === 0 || n.name || n.vorname) scan(\"nf.\" + i, F_NF, n, `${i + 1}. Kontakt`, i); });\n    if (!nurKontakte) scan(\"arzt\", F_ARZT, daten.arzt, \"Hausarzt\");\n    if (berater) scan(\"berater\", F_BERATER, berater, \"Berater\");\n    return out;\n  }\n\n  window.NFO = { VERWANDT, POSITION, F_KUNDE, F_NF, F_ARZT, F_BERATER, REQUIRED, RULES, t, esc, isoToDate, heute,\n    isRequired, checkValue, tidyValue, fieldHtml, fieldsHtml, datalists, showCheck, collectIssues };\n})();\n</script>\n<script>\n(() => {\n  const N = window.NFO, $ = (id) => document.getElementById(id);\n  const eid = decodeURIComponent(location.pathname.split(\"/\").pop() || \"\");\n  const ENTWURF = \"nfo-entwurf-\" + eid;\n  let daten = { nf: [{}, {}, {}] }, anzahl = 1, schluessel = null;\n  try { const d = JSON.parse(sessionStorage.getItem(ENTWURF) || \"null\"); if (d && d.daten) { daten = d.daten; anzahl = d.anzahl || 1; } } catch (e) {}\n  const merken = () => { try { sessionStorage.setItem(ENTWURF, JSON.stringify({ daten, anzahl })); } catch (e) {} };\n  $(\"lists\").innerHTML = N.datalists();\n\n  function render() {\n    $(\"kontakte\").innerHTML = [0, 1, 2].slice(0, anzahl).map((i) =>\n      `<div class=\"contact\"><div class=\"contact-head\"><h3>${i + 1}. Notfallkontakt</h3>${i > 0 && i === anzahl - 1 ? `<button type=\"button\" data-weg=\"${i}\">Entfernen</button>` : \"\"}</div>${N.fieldsHtml(\"nf.\" + i, N.F_NF, daten.nf[i])}</div>`\n    ).join(\"\");\n    $(\"mehr\").hidden = anzahl >= 3;\n    document.querySelectorAll(\"input[data-path]\").forEach((el) => N.showCheck(el, true, ctx()));\n    zusammenfassung();\n  }\n  const ctx = () => ({});\n  const obj = (path) => daten.nf[+path.split(\".\")[1]];\n  const probleme = () => N.collectIssues({ nf: daten.nf.slice(0, anzahl) }, null, true);\n  function zusammenfassung() {\n    const p = probleme(), s = $(\"summary\");\n    if (!p.length) { s.className = \"summary\"; s.textContent = \"Alles vollständig. Sie können jetzt senden.\"; }\n    else {\n      const inv = p.filter((x) => x.kind === \"invalid\").length, mis = p.length - inv;\n      s.className = \"summary warn\";\n      s.textContent = [inv ? `${inv} Eingabe${inv === 1 ? \"\" : \"n\"} prüfen` : \"\", mis ? `${mis} Pflichtfeld${mis === 1 ? \"\" : \"er\"} leer` : \"\"].filter(Boolean).join(\" · \");\n    }\n  }\n  document.addEventListener(\"input\", (e) => {\n    const el = e.target; if (!el.dataset || !el.dataset.path) return;\n    obj(el.dataset.path)[el.dataset.key] = el.value;\n    N.showCheck(el, false, ctx());\n    merken(); zusammenfassung();\n  });\n  document.addEventListener(\"focusout\", (e) => {\n    const el = e.target; if (!el.dataset || !el.dataset.path) return;\n    const n = N.tidyValue(el.dataset.key, el.value);\n    if (n !== el.value) { el.value = n; obj(el.dataset.path)[el.dataset.key] = n; merken(); }\n    N.showCheck(el, true, ctx()); zusammenfassung();\n  });\n  $(\"mehr\").onclick = () => { anzahl = Math.min(3, anzahl + 1); merken(); render(); document.getElementById(`in-nf-${anzahl - 1}-anrede`).focus(); };\n  $(\"kontakte\").addEventListener(\"click\", (e) => {\n    const b = e.target.closest(\"[data-weg]\"); if (!b) return;\n    daten.nf[+b.dataset.weg] = {}; anzahl--; merken(); render();\n  });\n  $(\"issues\").addEventListener(\"click\", (e) => {\n    const b = e.target.closest(\"[data-ziel]\"); if (!b) return;\n    const el = document.getElementById(b.dataset.ziel); if (el) { el.scrollIntoView({ block: \"center\", behavior: \"smooth\" }); el.focus({ preventScroll: true }); }\n  });\n\n  // ---------- Verschlüsseln ----------\n  const b64 = (buf) => { let s = \"\"; const b = new Uint8Array(buf); for (let i = 0; i < b.length; i += 0x8000) s += String.fromCharCode.apply(null, b.subarray(i, i + 0x8000)); return btoa(s); };\n  const unb64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));\n  async function verschluesseln(inhalt) {\n    const pub = await crypto.subtle.importKey(\"spki\", unb64(schluessel.pub), { name: \"RSA-OAEP\", hash: \"SHA-256\" }, false, [\"encrypt\"]);\n    const aes = await crypto.subtle.generateKey({ name: \"AES-GCM\", length: 256 }, true, [\"encrypt\"]);\n    const iv = crypto.getRandomValues(new Uint8Array(12));\n    const data = await crypto.subtle.encrypt({ name: \"AES-GCM\", iv }, aes, new TextEncoder().encode(JSON.stringify(inhalt)));\n    const roh = await crypto.subtle.exportKey(\"raw\", aes);\n    const key = await crypto.subtle.encrypt({ name: \"RSA-OAEP\" }, pub, roh);\n    return { v: 1, kid: schluessel.kid, key: b64(key), iv: b64(iv), data: b64(data) };\n  }\n\n  $(\"formular\").addEventListener(\"submit\", async (e) => {\n    e.preventDefault();\n    $(\"err\").textContent = \"\";\n    const p = probleme();\n    const ul = $(\"issues\");\n    if (p.length) {\n      ul.hidden = false;\n      ul.innerHTML = p.map((x) => `<li><button type=\"button\" data-ziel=\"in-${x.path.replace(/\\./g, \"-\")}-${x.k}\">${N.esc(x.text)}</button> – ${N.esc(x.why)}</li>`).join(\"\");\n      document.querySelectorAll(\"input[data-path]\").forEach((el) => N.showCheck(el, true, ctx()));\n      $(\"err\").textContent = \"Bitte zuerst die markierten Angaben ergänzen oder korrigieren.\";\n      return;\n    }\n    ul.hidden = true;\n    if (!$(\"ok\").checked) { $(\"err\").textContent = \"Bitte bestätigen Sie die Einverständniserklärung.\"; $(\"ok\").focus(); return; }\n    const btn = $(\"senden\"); btn.disabled = true; btn.textContent = \"Wird verschlüsselt und gesendet …\";\n    try {\n      const umschlag = await verschluesseln({ nf: daten.nf.slice(0, anzahl), gesendet: new Date().toISOString() });\n      const r = await fetch(\"/api/submit/\" + encodeURIComponent(eid), { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify(umschlag) });\n      const a = await r.json().catch(() => ({}));\n      if (!r.ok) throw new Error(a.error || \"Senden fehlgeschlagen\");\n      try { sessionStorage.removeItem(ENTWURF); } catch (e2) {}\n      $(\"formular\").hidden = true; $(\"fertig\").hidden = false; window.scrollTo(0, 0);\n    } catch (err) {\n      $(\"err\").textContent = (err && err.message ? err.message : \"Senden fehlgeschlagen\") + \". Bitte erneut versuchen.\";\n      btn.disabled = false; btn.textContent = \"Verschlüsselt senden\";\n    }\n  });\n\n  // ---------- Start ----------\n  (async () => {\n    const zeige = (id) => { $(\"laden\").hidden = true; $(id).hidden = false; };\n    try {\n      if (!window.crypto || !crypto.subtle) throw new Error(\"alt\");\n      const [s, k] = await Promise.all([fetch(\"/api/invite/\" + encodeURIComponent(eid)).then((r) => r.json()), fetch(\"/api/key\").then((r) => r.ok ? r.json() : null)]);\n      if (s.status === \"verwendet\") { $(\"ungueltigTitel\").textContent = \"Ihre Notfallkontakte wurden bereits gesendet\"; $(\"ungueltigText\").textContent = \"Dieser Link kann nur einmal verwendet werden. Für Änderungen wenden Sie sich bitte an Ihren Berater.\"; return zeige(\"ungueltig\"); }\n      if (s.status !== \"offen\" || !k) return zeige(\"ungueltig\");\n      schluessel = k;\n      const b = k.berater || {};\n      $(\"beraterName\").textContent = b.name || \"–\";\n      $(\"dsHinweis\").textContent = b.datenschutz ? b.datenschutz : (b.name ? `Verantwortlich für die Verarbeitung ist ${b.name}${b.mail ? \", \" + b.mail : \"\"}.` : \"\");\n      document.title = \"Notfallordner – Ihre Notfallkontakte\";\n      zeige(\"formular\");\n      render();\n    } catch (e) {\n      $(\"ungueltigTitel\").textContent = \"Das Formular konnte nicht geladen werden\";\n      $(\"ungueltigText\").textContent = e && e.message === \"alt\" ? \"Ihr Browser ist zu alt. Bitte öffnen Sie den Link in einem aktuellen Browser.\" : \"Bitte prüfen Sie Ihre Internetverbindung und laden Sie die Seite neu.\";\n      zeige(\"ungueltig\");\n    }\n  })();\n})();\n</script>\n</body>\n</html>\n";

const TAG = 24 * 3600;
const EINLADUNG_TTL = 60 * TAG; // unbenutzte Links verfallen nach 60 Tagen
const EINGANG_TTL = 30 * TAG; // nicht abgeholte Einsendungen verfallen nach 30 Tagen
const MAX_GROESSE = 64 * 1024;
const ID = /^[A-Za-z0-9_-]{16,64}$/;

const SICHERHEIT = {
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "no-referrer",
  "X-Frame-Options": "DENY",
  "Cache-Control": "no-store",
};

const json = (daten, status = 200) =>
  new Response(JSON.stringify(daten), { status, headers: { "Content-Type": "application/json; charset=utf-8", ...SICHERHEIT } });

async function gleich(a, b) {
  // Vergleich in konstanter Zeit über Hashes
  const enc = new TextEncoder();
  const [x, y] = await Promise.all([crypto.subtle.digest("SHA-256", enc.encode(a)), crypto.subtle.digest("SHA-256", enc.encode(b))]);
  const ax = new Uint8Array(x), ay = new Uint8Array(y);
  let d = 0;
  for (let i = 0; i < ax.length; i++) d |= ax[i] ^ ay[i];
  return d === 0;
}

async function istAdmin(req, env) {
  const h = req.headers.get("Authorization") || "";
  const token = h.startsWith("Bearer ") ? h.slice(7) : "";
  if (!env.ADMIN_TOKEN || env.ADMIN_TOKEN.length < 24 || !token) return false;
  return gleich(token, env.ADMIN_TOKEN);
}

// Verzeichnis der wartenden Einsendungen (spart teure list()-Abfragen im kostenlosen Tarif)
async function verzeichnis(env) { return (await env.NFO.get("inbox-index", "json")) || []; }
async function verzeichnisSetzen(env, ids) { await env.NFO.put("inbox-index", JSON.stringify([...new Set(ids)])); }

async function leseJson(req) {
  const text = await req.text();
  if (text.length > MAX_GROESSE) throw new Error("zu groß");
  return JSON.parse(text);
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const p = url.pathname;
    const m = req.method;
    try {
      // ---------- Kundenformular ----------
      let r;
      if (m === "GET" && (r = p.match(/^\/f\/([^/]+)$/))) {
        return new Response(FORMULAR_HTML, {
          headers: {
            "Content-Type": "text/html; charset=utf-8",
            "Content-Security-Policy": "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; connect-src 'self'; img-src data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
            ...SICHERHEIT,
          },
        });
      }
      if (m === "GET" && p === "/") {
        return new Response("Notfallordner-Briefkasten", { headers: { "Content-Type": "text/plain; charset=utf-8", ...SICHERHEIT } });
      }

      // ---------- Öffentliche API für das Formular ----------
      if (m === "GET" && p === "/api/key") {
        const key = await env.NFO.get("key", "json");
        return key ? json({ pub: key.pub, kid: key.kid, berater: key.berater || {} }) : json({ error: "kein Schlüssel" }, 503);
      }
      if (m === "GET" && (r = p.match(/^\/api\/invite\/([^/]+)$/))) {
        if (!ID.test(r[1])) return json({ status: "unbekannt" });
        const inv = await env.NFO.get("invite:" + r[1], "json");
        return json({ status: inv ? inv.status : "unbekannt" });
      }
      if (m === "POST" && (r = p.match(/^\/api\/submit\/([^/]+)$/))) {
        const id = r[1];
        if (!ID.test(id)) return json({ error: "Link ungültig" }, 404);
        const inv = await env.NFO.get("invite:" + id, "json");
        if (!inv) return json({ error: "Link ungültig oder abgelaufen" }, 404);
        if (inv.status !== "offen") return json({ error: "Dieser Link wurde bereits verwendet" }, 409);
        let u;
        try { u = await leseJson(req); } catch (e) { return json({ error: "Daten unlesbar" }, 400); }
        if (!u || u.v !== 1 || typeof u.key !== "string" || typeof u.iv !== "string" || typeof u.data !== "string") {
          return json({ error: "Daten unvollständig" }, 400);
        }
        const eintrag = { id, received: Date.now(), envelope: { v: 1, kid: String(u.kid || ""), key: u.key, iv: u.iv, data: u.data } };
        await env.NFO.put("inbox:" + id, JSON.stringify(eintrag), { expirationTtl: EINGANG_TTL });
        await env.NFO.put("invite:" + id, JSON.stringify({ ...inv, status: "verwendet", used: Date.now() }), { expirationTtl: EINGANG_TTL });
        await verzeichnisSetzen(env, [...(await verzeichnis(env)), id]);
        return json({ ok: true });
      }

      // ---------- Verwaltung (nur mit Zugangsschlüssel) ----------
      if (p.startsWith("/api/admin/")) {
        if (!(await istAdmin(req, env))) return json({ error: "nicht berechtigt" }, 401);
        if (m === "GET" && p === "/api/admin/ping") {
          const key = await env.NFO.get("key", "json");
          return json({ ok: true, kid: key ? key.kid : null });
        }
        if (m === "PUT" && p === "/api/admin/key") {
          const d = await leseJson(req);
          if (typeof d.pub !== "string" || d.pub.length < 100 || typeof d.kid !== "string") return json({ error: "Schlüssel ungültig" }, 400);
          const s = (v, n) => String(v || "").slice(0, n);
          const ber = d.berater || {};
          const berater = { name: s(ber.name, 120), mail: s(ber.mail, 120), tel: s(ber.tel, 60), datenschutz: s(ber.datenschutz, 2000) };
          await env.NFO.put("key", JSON.stringify({ pub: d.pub, kid: d.kid, berater, set: Date.now() }));
          return json({ ok: true });
        }
        if (m === "POST" && p === "/api/admin/invite") {
          const d = await leseJson(req);
          if (!ID.test(d.id || "")) return json({ error: "ID ungültig" }, 400);
          await env.NFO.put("invite:" + d.id, JSON.stringify({ status: "offen", created: Date.now() }), { expirationTtl: EINLADUNG_TTL });
          return json({ ok: true });
        }
        if (m === "DELETE" && (r = p.match(/^\/api\/admin\/invite\/([^/]+)$/))) {
          await env.NFO.delete("invite:" + r[1]);
          return json({ ok: true });
        }
        if (m === "GET" && p === "/api/admin/inbox") {
          const idx = await verzeichnis(env);
          let ids = idx;
          if (url.searchParams.get("voll") === "1") {
            // gelegentlich vollständig nachsehen, falls das Verzeichnis etwas verpasst hat
            const list = await env.NFO.list({ prefix: "inbox:" });
            ids = [...new Set([...idx, ...list.keys.map((k) => k.name.slice(6))])];
          }
          const items = [], da = [];
          for (const id of ids) {
            const v = await env.NFO.get("inbox:" + id, "json");
            if (v) { items.push(v); da.push(id); }
          }
          if (da.length !== idx.length || da.some((x) => !idx.includes(x))) await verzeichnisSetzen(env, da);
          return json({ items });
        }
        if (m === "DELETE" && (r = p.match(/^\/api\/admin\/inbox\/([^/]+)$/))) {
          await env.NFO.delete("inbox:" + r[1]);
          await verzeichnisSetzen(env, (await verzeichnis(env)).filter((x) => x !== r[1]));
          return json({ ok: true });
        }
      }
      return json({ error: "nicht gefunden" }, 404);
    } catch (e) {
      return json({ error: "Fehler im Briefkasten" }, 500);
    }
  },
};
